<script setup>
import {ref} from 'vue';
const props=defineProps({modelValue:{type:String,default:''}});const emit=defineEmits(['update:modelValue']);const helper=ref(false);const algorithm=ref('X25519');const key=ref('');const secret=ref('');const notice=ref('');
function apply(){if(!key.value.trim()){notice.value='请先填写或派生公钥';return}emit('update:modelValue',key.value.trim());notice.value='已填入公钥字段'}
function generate(){secret.value='AGE-SECRET-KEY-DEMO-'+algorithm.value;key.value='age1demo-'+algorithm.value;notice.value='已生成演示占位值，不能用于真实加密'}
function derive(){if(!secret.value){notice.value='请先输入私钥';return}key.value='age1derived-demo-'+algorithm.value;notice.value='演示派生流程：正式版本由原版后端 API 派生公钥'}
async function copy(value){try{await navigator.clipboard.writeText(value);notice.value='已复制演示密钥'}catch{notice.value='请手动选择并复制'}}
</script>
<template><section><FormKit :model-value="modelValue" :ignore="true" label="age 加密公钥" @input="emit('update:modelValue',$event)"/><button class="button" type="button" @click="helper=!helper">密钥助手</button><div v-if="helper" class="processor-card"><FormKit v-model="algorithm" type="select" :ignore="true" label="密钥类型" :options="['X25519','MLKEM768-X25519']"/><FormKit v-model="secret" type="textarea" :ignore="true" label="私钥"/><div class="resource-row"><button type="button" class="button" @click="generate">生成示例密钥</button><button type="button" class="button" :disabled="!secret" @click="copy(secret)">复制私钥</button><button type="button" class="button" :disabled="!secret" @click="secret=''">清空私钥</button></div><FormKit v-model="key" type="textarea" :ignore="true" label="公钥"/><div class="resource-row"><button type="button" class="button" :disabled="!secret" @click="derive">从私钥派生公钥</button><button type="button" class="button" :disabled="!key" @click="copy(key)">复制公钥</button><button type="button" class="button primary" @click="apply">填入公钥</button><button type="button" class="button" @click="key=''">清空公钥</button></div><p class="field-note">示例数据，不请求密钥生成或派生 API。</p><p v-if="notice" role="status" class="field-note">{{notice}}</p></div></section></template>
